// ADS-B category -> fallback shape
inline const char* category_to_shape(uint8_t cat) {
    switch (cat) {
        case 0xA1: return "cessna";
        case 0xA2: return "single_turbo";
        case 0xA3: return "a320";
        case 0xA4: return "a332";
        case 0xA5: return "a332";
        case 0xA6: return "hi_perf";
        case 0xA7: return "helicopter";
        case 0xB1: return "glider";
        case 0xB2: return "balloon";
        case 0xB4: return "cessna";
        case 0xB6: return "uav";
        case 0xC1: case 0xC2: return "ground_square";
        default:   return "airliner";
    }
}

// lookup shape by type code (with prefix match) then category fallback
inline const Shape* lookup(const char* type_code, uint8_t category) {
    if (type_code && type_code[0] != '\0') {
        int len = 0;
        while (type_code[len] && len < 4) ++len;
        // try prefix match (longest first)
        for (int i = 0; i < k_type_map_count; ++i) {
            const char* p = k_type_map[i].prefix;
            int plen = 0;
            while (p[plen]) ++plen;
            if (plen <= len) {
                bool match = true;
                for (int j = 0; j < plen; ++j)
                    if (type_code[j] != p[j]) { match = false; break; }
                if (match)
                    return find_shape(k_type_map[i].shape);
            }
        }
    }
    return find_shape(category_to_shape(category));
}

